// augments the global `Error` like effect does
declare global {
  interface Error {
    readonly '~augments/severity'?: 'error' | 'warn'
    readonly '~augments/reported': boolean
  }
}

export interface Reporter {
  report(error: Error): void
}

/** Declared like effect's opaque schema types: the constructor does not create the interface */
export interface Opaque {
  tags: Set<string>
}

export declare const Opaque: { new (_: never): {} }

/** Declared like a library class */
export interface Session {
  readonly id: string
  tags: Set<string>
}

export declare const Session: { new (): Session }

/** Constructors creating their interface through other types */
export interface Branded {
  tags: Set<string>
}

export declare const Branded: { new (): Branded & { readonly __brand: 'branded' } }

export interface Frozen {
  tags: Set<string>
}

export declare const Frozen: { new (): Readonly<Frozen> }

export interface Generic {
  tags: Set<string>
}

export declare const Generic: { new <T extends Generic = Generic>(): T }

export interface Animal {
  tags: Set<string>
}

export interface Dog extends Animal {
  barks: boolean
}

export declare const Animal: { new (): Dog }
